     1→//! ELF utility functions for func-analysis
     2→
     3→use anyhow::{Context, Result};
     4→use goblin::elf::Elf;
     5→use std::collections::HashMap;
     6→use std::fs;
     7→use std::path::Path;
     8→
     9→/// Get the size of the .text section
    10→pub fn get_text_section_size(elf: &Elf) -> u64 {
    11→    elf.section_headers
    12→        .iter()
    13→        .find(|sh| elf.shdr_strtab.get_at(sh.sh_name).unwrap_or("") == ".text")
    14→        .map(|sh| sh.sh_size)
    15→        .unwrap_or(0)
    16→}
    17→
    18→/// Build a map of function names to their PLT addresses
    19→pub fn build_plt_map(elf: &Elf) -> Result<HashMap<String, u64>> {
    20→    let mut plt_map = HashMap::new();
    21→
    22→    // Find .rela.plt section for PLT relocations
    23→    for reloc in &elf.pltrelocs {
    24→        let sym_idx = reloc.r_sym;
    25→        if let Some(sym) = elf.dynsyms.get(sym_idx) {
    26→            let name = elf.dynstrtab.get_at(sym.st_name).unwrap_or("???");
    27→
    28→            // PLT entry address: typically the relocation target + PLT base
    29→            // This is simplified; real PLT layout varies
    30→            if let Some(plt_shdr) = elf
    31→                .section_headers
    32→                .iter()
    33→                .find(|sh| elf.shdr_strtab.get_at(sh.sh_name).unwrap_or("") == ".plt")
    34→            {
    35→                // Each PLT entry is typically 16 bytes on x86_64
    36→                // First entry is resolver, real entries start at +16
    37→                let plt_entry_addr = plt_shdr.sh_addr + 16 + (plt_map.len() as u64 * 16);
    38→                plt_map.insert(name.to_string(), plt_entry_addr);
    39→            }
    40→        }
    41→    }
    42→
    43→    Ok(plt_map)
    44→}
    45→
    46→/// Load function sizes from a glibc shared library
    47→pub fn load_libc_sizes(libc_path: &Path) -> Result<HashMap<String, u64>> {
    48→    let data = fs::read(libc_path)
    49→        .with_context(|| format!("Failed to read libc: {:?}", libc_path))?;
    50→
    51→    let elf = Elf::parse(&data)?;
    52→    let mut sizes = HashMap::new();
    53→
    54→    for sym in &elf.dynsyms {
    55→        if sym.st_type() == goblin::elf::sym::STT_FUNC && sym.st_size > 0 {
    56→            let name = elf.dynstrtab.get_at(sym.st_name).unwrap_or("???");
    57→            sizes.insert(name.to_string(), sym.st_size);
    58→        }
    59→    }
    60→
    61→    // Also check regular symtab if available
    62→    for sym in &elf.syms {
    63→        if sym.st_type() == goblin::elf::sym::STT_FUNC && sym.st_size > 0 {
    64→            let name = elf.strtab.get_at(sym.st_name).unwrap_or("???");
    65→            sizes.entry(name.to_string()).or_insert(sym.st_size);
    66→        }
    67→    }
    68→
    69→    Ok(sizes)
    70→}
    71→
    72→#[cfg(test)]
    73→mod tests {
    74→    use super::*;
    75→    use crate::test_utils::build_test_binary;
    76→
    77→    #[test]
    78→    fn test_get_text_section_size() {
    79→        let binary_path = build_test_binary();
    80→        let binary_data = fs::read(&binary_path).expect("Failed to read binary");
    81→        let elf = Elf::parse(&binary_data).expect("Failed to parse ELF");
    82→
    83→        let text_size = get_text_section_size(&elf);
    84→        assert!(text_size > 0, ".text section should have non-zero size");
    85→    }
    86→
