/// Extract the target address from a call instruction
fn extract_call_target(instruction: &Instruction) -> Option<u64> {
    use iced_x86::{OpKind, Register};

    if instruction.is_call_near_indirect() {
        // Check for RIP-relative indirect call: call *offset(%rip)
        // This is used for GOT-direct calls in PLT-less binaries
        if instruction.op0_kind() == OpKind::Memory && instruction.memory_base() == Register::RIP {
            // Compute the absolute address: instruction_end + displacement
            let target = instruction
                .ip()
                .wrapping_add(instruction.len() as u64)
                .wrapping_add(instruction.memory_displacement64());
            return Some(target);
        }
        // Other indirect calls (call *%rax, call *(%rbx), etc.) can't be resolved statically
        None
    } else {
        // Direct calls - iced-x86 computes the absolute target for us
        let target = instruction.near_branch_target();
        if target != 0 {
            Some(target)
        } else {
            None
        }
    }
}

